ee:message.ee:set-payload:
%dw 2.0
output application/json
var validCombinations = [
    "CONNECTION_NUMBER",
    "CONNECTION_NUMBER and BILLING_ACCOUNT",
    "CUSTOMER_ID_TYPE and CUSTOMER_ID"
  ]
var errorMsg = error.description ++ ": " ++ write(validCombinations, "application/java")
---
{
    "status": "400",
    "code": "HTTP:BAD_REQUEST",
    "message": errorMsg,
    "messageServer": error.failingComponent default "VALIDATION:INVALID_BOOLEAN",
    "cause": [
        {
            "origin": "customer-papi-services-v2",
            "message": errorMsg
        }
    ]
}
